  "implementation": "import math
def solve(case):
    matrix = case['matrix']
    idf = case['idf']
    vector = case['vector']
    N = len(vector)
    M = len(idf)
    if len(matrix) != N:
        raise ValueError("Matrix row count must match vector length")
    for i, row in enumerate(matrix):
        if len(row) != M:
            raise ValueError(f"Matrix row {i} length mismatch with IDF length")
    W = [[matrix[i][j] * idf[j] for j in range(M)] for i in range(N)]
    eps = 1e-10
    degree = [max(sum(W[i][j]**2 for j in range(M)), eps) for i in range(N)]
    v_scaled = [vector[i] / math.sqrt(degree[i]) for i in range(N)]
    t = [0.0] * M
    for j in range(M):
        s = 0.0
        for i in range(N):
            s += W[i][j] * v_scaled[i]
        t[j] = s
    result = [0.0] * N
    for i in range(N):
        s = 0.0
        for j in range(M):
            s += W[i][j] * t[j]
        result[i] = s
    result = [result[i] / math.sqrt(degree[i]) for i in range(N)]
    return {'degree': degree, 'result': result}"
}
